import{mockPublicApi}from'./fixtures/api-mock';
import{test,expect}from'@playwright/test';test.beforeEach(async({page})=>mockPublicApi(page));test('reserva W2 carga flujo real',async({page})=>{await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Cancha Central',tipo:'CUBIERTA',duracionMinutos:90,precio:25000,importeSenia:6250,tieneIluminacion:true}]}));await page.goto('/w2/reservar');await expect(page.locator('#listaCanchasReserva .reserve-court')).toHaveCount(1);await page.locator('.reserve-court').click();await expect(page.locator('#buscarHorarios')).toBeEnabled()});
test('reserva W2 presenta selección y formulario premium',async({page})=>{await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Cancha 2',tipo:'CUBIERTA',superficie:'Césped sintético',duracionMinutos:90,precio:25000,importeSenia:6250,tieneIluminacion:true}]}));await page.goto('/w2/reservar');await page.locator('.reserve-court').click();await expect(page.locator('.reserve-court')).toHaveClass(/selected/);await expect(page.locator('.reserve-court-choice')).toContainText('Cancha elegida');await expect(page.locator('#buscarHorarios')).toBeEnabled();await expect(page.locator('.reserve-quantity')).toHaveCount(1);await expect(page.locator('#clienteDocumento')).not.toHaveAttribute('readonly','')});

test('reserva W2 traslada pasos y habilita navegación hacia atrás',async({page})=>{await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Cancha Principal',tipo:'CUBIERTA',superficie:'Césped sintético',duracionMinutos:90,precio:25000,importeSenia:6250,tieneIluminacion:true}]}));await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-14',cancha:{id:1,nombre:'Cancha Principal',duracionMinutos:90},disponibleEseDia:true,horarios:[{horaInicio:'12:30:00',horaFin:'14:00:00',precio:25000,importeSenia:6250}]}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').click();await page.locator('#buscarHorarios').click();await expect(page.locator('[data-panel="2"]')).toBeVisible();await expect(page.locator('[data-paso-indicador="1"]')).toHaveClass(/navegable/);await page.locator('[data-paso-indicador="1"]').click();await expect(page.locator('[data-panel="1"]')).toBeVisible();const top=await page.locator('[data-panel="1"] [data-paso-ancla]').evaluate(el=>el.getBoundingClientRect().top);const stepsBottom=await page.locator('.reserve-steps').evaluate(el=>el.getBoundingClientRect().bottom);expect(top).toBeGreaterThanOrEqual(stepsBottom-2)});test('formato del turno fija cuatro jugadores',async({page})=>{await page.goto('/w2/reservar');await expect(page.locator('.w2b-player-format')).toContainText('4 jugadores');await expect(page.locator('.w2b-player-format')).toContainText('2 contra 2');await expect(page.locator('#cantidadJugadores')).toHaveAttribute('type','hidden');await expect(page.locator('#cantidadJugadores')).toHaveValue('4');await expect(page.locator('.reserve-quantity')).toHaveCount(0)});

test('ancla interna mantiene encabezado visible al volver y avanzar',async({page})=>{await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Cancha 2',tipo:'CUBIERTA',superficie:'Césped sintético',duracionMinutos:90,precio:25000,importeSenia:6250,tieneIluminacion:true}]}));await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-14',cancha:{id:1,nombre:'Cancha 2',duracionMinutos:90},disponibleEseDia:true,horarios:[{horaInicio:'08:00:00',horaFin:'09:30:00',precio:25000,importeSenia:6250}]}}));await page.route('**/api/publica/cliente/perfil',r=>r.fulfill({json:{nombre:'Facundo',apellido:'Vitale',documento:'38928193',telefono:'2200000000',email:'f@example.com'}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').click();await expect(page.locator('[data-panel="3"]')).toBeVisible();await page.waitForTimeout(850);for(const panel of ['3']){const top=await page.locator('[data-panel="'+panel+'"] [data-paso-ancla]').evaluate(el=>el.getBoundingClientRect().top);const bottom=await page.locator('.reserve-steps').evaluate(el=>el.getBoundingClientRect().bottom);expect(top).toBeGreaterThanOrEqual(bottom+16)}await page.locator('[data-paso-indicador="1"]').click();await page.waitForTimeout(850);const top1=await page.locator('[data-panel="1"] [data-paso-ancla]').evaluate(el=>el.getBoundingClientRect().top);const bottom1=await page.locator('.reserve-steps').evaluate(el=>el.getBoundingClientRect().bottom);expect(top1).toBeGreaterThanOrEqual(bottom1+16)});test('consentimiento cambia una sola vez',async({page})=>{await page.goto('/w2/reservar');const check=page.locator('#aceptarCondiciones');await check.evaluate((el:HTMLInputElement)=>el.click());await expect(check).toBeChecked();await check.evaluate((el:HTMLInputElement)=>el.click());await expect(check).not.toBeChecked()});

test('calendario W2 reemplaza selector nativo y actualiza fecha',async({page})=>{await page.goto('/w2/reservar');await expect(page.locator('#fechaReserva')).toHaveAttribute('type','hidden');await page.locator('#w2calTrigger').click();await expect(page.locator('#w2calPopover')).toBeVisible();const day=page.locator('#w2calDays button:not([disabled])').last();await day.click();await expect(page.locator('#w2calValue')).not.toHaveText('Seleccionar fecha')});test('cambio de paso no hace corrección tardía visible',async({page})=>{await page.route('**/api/publica/complejo',r=>r.fulfill({json:{moneda:'ARS',colorPrincipal:'#d7192d',anticipacionMinimaHoras:2,minutosReservaPendiente:10,porcentajeSenia:25,pagoTransferenciaDisponible:true}}));await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Cancha 2',duracionMinutos:90,precio:25000,importeSenia:6250}]}));await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-14',cancha:{id:1,nombre:'Cancha 2',duracionMinutos:90},disponibleEseDia:true,horarios:[{horaInicio:'08:00:00',horaFin:'09:30:00',precio:25000,importeSenia:6250}]}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').click();await page.locator('#buscarHorarios').click();await page.waitForTimeout(100);const first=await page.evaluate(()=>scrollY);await page.waitForTimeout(700);const second=await page.evaluate(()=>scrollY);expect(Math.abs(second-first)).toBeLessThan(3)});


test('calendario conserva scroll al abrir cambiar mes y cerrar',async({page})=>{await page.goto('/w2/reservar');await page.locator('#w2calTrigger').scrollIntoViewIfNeeded();const initial=await page.evaluate(()=>scrollY);await page.locator('#w2calTrigger').evaluate((el:HTMLElement)=>el.click());await page.waitForTimeout(80);expect(Math.abs((await page.evaluate(()=>scrollY))-initial)).toBeLessThan(2);await page.locator('[data-w2cal-next]').click();expect(Math.abs((await page.evaluate(()=>scrollY))-initial)).toBeLessThan(2);await page.locator('[data-w2cal-close]').last().click();await page.waitForTimeout(170);expect(Math.abs((await page.evaluate(()=>scrollY))-initial)).toBeLessThan(2)});

test('calendario siempre abre debajo en escritorio y bottom sheet en movil',async({page})=>{await page.goto('/w2/reservar');const width=await page.evaluate(()=>innerWidth);const trigger=page.locator('#w2calTrigger');await trigger.scrollIntoViewIfNeeded();const before=await page.evaluate(()=>scrollY);const tr=await trigger.evaluate(el=>el.getBoundingClientRect());await trigger.evaluate((el:HTMLElement)=>el.click());await page.waitForTimeout(80);await expect(page.locator('#w2calPopover')).not.toHaveClass(/above/);const rect=await page.locator('.w2cal-panel').evaluate(el=>el.getBoundingClientRect());if(width>520){expect(rect.top).toBeGreaterThanOrEqual(tr.bottom+6);expect(rect.top-tr.bottom).toBeLessThanOrEqual(12);}else expect(rect.bottom).toBeLessThanOrEqual(await page.evaluate(()=>innerHeight));expect(Math.abs((await page.evaluate(()=>scrollY))-before)).toBeLessThan(2)});

test('paso 4 permanece visible y usa la orden real de pago',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#formReserva').evaluate((form:HTMLFormElement)=>{for(const [id,value] of Object.entries({clienteNombre:'Ana',clienteApellido:'Prueba',clienteDocumento:'30123456',clienteTelefono:'1112345678',clienteEmail:'ana@example.test'})){const input=form.querySelector<HTMLInputElement>('#'+id);if(input)input.value=value}});await page.locator('#enviarReserva').click();await expect(page.locator('[data-pay-manual]')).toBeVisible();await page.locator('[data-pay-manual]').click();await expect(page.locator('[data-panel="4"]')).toBeVisible();await expect(page.locator('.reserve-confirmation-shell')).toBeVisible();await expect(page.locator('#contadorReserva')).toHaveText(/\d{2}:\d{2}/);await expect(page.locator('#bloquePagoReserva')).toContainText('Completá la seña en tres pasos');await expect(page.locator('#irSeguimientoReserva')).toHaveAttribute('href',/reserva=901/);await page.waitForTimeout(1100);await expect(page).toHaveURL(/\/w2\/reservar/)});

test('confirmacion sincroniza lateral bloquea pasos y ofrece comprobante',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#formReserva').evaluate((form:HTMLFormElement)=>{for(const [id,value] of Object.entries({clienteNombre:'Ana',clienteApellido:'Prueba',clienteDocumento:'30123456',clienteTelefono:'1112345678',clienteEmail:'ana@example.test'})){const input=form.querySelector<HTMLInputElement>('#'+id);if(input)input.value=value}});await page.locator('#enviarReserva').click();await expect(page.locator('[data-pay-manual]')).toBeVisible();await page.locator('[data-pay-manual]').click();await expect(page.locator('#datoProteccionReserva')).toHaveText(/\d{2}:\d{2}/);await expect(page.locator('#datoSeniaReserva')).toContainText('6.250');await expect(page.locator('[data-paso-indicador="1"]')).toHaveAttribute('aria-disabled','true');await expect(page.locator('.reserve-payment-steps')).toBeVisible();await expect(page.locator('#enviarComprobanteReserva')).toHaveAttribute('href');expect(await page.locator('#enviarComprobanteReserva').getAttribute('href')).toMatch(/^https:/);expect(await page.locator('#enviarComprobanteReserva').getAttribute('href')).toContain('wa.me/');await expect(page.locator('.reserve-confirmation-tracking strong')).toHaveText(/…/)});

test('microcierre evita redundancias y muestra estado contextual',async({page})=>{const {mockPublicApi}=await import('./fixtures/api-mock');await mockPublicApi(page,{authenticated:true});await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await page.locator('.reserve-time').first().click();await page.locator('#aceptarCondiciones').check();await page.locator('#formReserva').evaluate((form:HTMLFormElement)=>{for(const [id,value] of Object.entries({clienteNombre:'Ana',clienteApellido:'Prueba',clienteDocumento:'30123456',clienteTelefono:'1112345678',clienteEmail:'ana@example.test'})){const input=form.querySelector<HTMLInputElement>('#'+id);if(input)input.value=value}});await page.locator('#enviarReserva').click();await expect(page.locator('[data-pay-manual]')).toBeVisible();await page.locator('[data-pay-manual]').click();await expect(page.locator('#estadoReservaLateral')).toHaveText('Esperando acreditación');await expect(page.locator('#estadoReservaLateral')).toBeVisible();await expect(page.locator('.reserve-payment-steps li').nth(2)).toContainText('código de seguimiento');await expect(page.locator('.reserve-payment-note')).toContainText('consultar el estado actualizado');await expect(page.locator('.reserve-payment-note')).not.toContainText('enviá el comprobante')});

test('pulido final sincroniza fecha y CTA transparente',async({page})=>{await page.goto('/w2/reservar');await expect.poll(async()=>page.locator('#fechaReserva').inputValue()).toMatch(/^\d{4}-\d{2}-\d{2}$/);await expect(page.locator('#w2calValue')).not.toHaveText('Seleccionar fecha');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await expect(page.locator('.reserve-time-choice').first()).toContainText(/Elegir \d{2}:\d{2}/)});
test('pulido final mantiene consentimiento sereno y selector proporcionado',async({page})=>{await page.goto('/w2/reservar');const consent=page.locator('.reserve-consent');await page.locator('#aceptarCondiciones').evaluate((el:HTMLInputElement)=>el.click());await expect(consent).toHaveClass(/checked/);const shadow=await consent.evaluate(el=>getComputedStyle(el).boxShadow);expect(shadow).toBe('none');const quantity=page.locator('.reserve-quantity');if(await page.evaluate(()=>innerWidth>520))expect(await quantity.evaluate(el=>el.getBoundingClientRect().width)).toBeLessThanOrEqual(221)});


test('checkout creado sin URL ofrece recuperación segura', async ({ page }) => {
  await page.route('**/api/publica/cliente/pagos/capacidades', r => r.fulfill({json:{pagoOnlineDisponible:true,pagoTransferenciaDisponible:true,entornoOnline:'sandbox'}}));
  await page.route('**/api/publica/cliente/reservas/*/pago', async r => {
    if(r.request().method()==='GET') return r.fulfill({json:{ordenId:41,estado:'CREADA',metodo:'PAGO_ONLINE',importe:6250,moneda:'ARS',segundosRestantes:420,mensaje:'La reserva sigue protegida.'}});
    return r.fulfill({json:{ordenId:41,estado:'ESPERANDO_PAGO',metodo:'PAGO_ONLINE',checkoutUrl:'https://www.mercadopago.com.ar/checkout/v1/redirect',segundosRestantes:420}});
  });
  await page.goto('/w2/cuenta');
  await page.evaluate(() => { const host=document.createElement('div');host.dataset.w2pHost='';document.body.append(host); });
});


test('drawer de pago mantiene estados excluyentes', async ({ page }) => {
  await page.goto('/w2/cuenta');
  const source = await page.request.get('/src/w2/scripts/cuenta.ts');
  expect(await source.text()).toContain('w2pNormalizarDrawer');
});


test('paleta semantica mantiene identidad W2', async ({ page }) => {
  const css=await page.request.get('/src/w2/styles/w2-account.css');
  const text=await css.text();
  expect(text).toContain('P4.9H - coherencia cromatica definitiva');
  expect(text).toContain('--w2-pay-positive');
  expect(text).toContain('--w2-pay-warning');
  expect(text).toContain('--w2-pay-provider');
});


test('drawer integra cierre delegado y skeleton estable', async ({ page }) => {
  const response=await page.request.get('/src/w2/scripts/cuenta.ts');
  expect(response.ok()).toBeTruthy();
  const text=await response.text();
  expect(text).toMatch(/target\.closest\([\"']#w2rDetailClose[\"']\)/);
  expect(text).toMatch(/classList\.add\([\"']w2p-resolving[\"']\)/);
  expect(text).toMatch(/w2pRenderPayment\(paymentHost,\s*r\)/);
});

test('W2.5A1 compara alternativas del día',async({page})=>{await page.route('**/api/publica/canchas',r=>r.fulfill({json:[{id:1,nombre:'Central',tipo:'Cubierta',tieneIluminacion:true,horaApertura:'08:00:00',horaCierre:'23:00:00',duracionMinutos:90,precio:25000,importeSenia:6250,diasDisponibles:['LUNES']},{id:2,nombre:'Norte',tipo:'Panorámica',tieneIluminacion:true,horaApertura:'09:00:00',horaCierre:'23:00:00',duracionMinutos:90,precio:28000,importeSenia:7000,diasDisponibles:['LUNES']}]}));await page.route('**/api/publica/disponibilidad**',r=>{const id=new URL(r.request().url()).searchParams.get('canchaId');return r.fulfill({json:{fecha:'2026-10-20',cancha:{id:Number(id),nombre:id==='1'?'Central':'Norte',duracionMinutos:90},disponibleEseDia:true,horarios:id==='1'?[{horaInicio:'10:00:00',horaFin:'11:30:00',precio:25000,importeSenia:6250}]:[{horaInicio:'19:00:00',horaFin:'20:30:00',precio:28000,importeSenia:7000},{horaInicio:'21:00:00',horaFin:'22:30:00',precio:28000,importeSenia:7000}]}})});await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await expect(page.locator('.w2b-availability-card')).toHaveCount(2);await expect(page.locator('#w2bAvailabilitySummary')).toContainText('3 horarios disponibles');await page.locator('[data-alternative-court="2"]').click();await expect(page.locator('#tituloHorarios')).toContainText('Norte');await expect(page.locator('.reserve-time')).toHaveCount(2);await expect(page.locator('.reserve-time').first()).toContainText('NOCHE')});
test('W2.5A1 informa agenda completa sin perder alternativas',async({page})=>{await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-20',cancha:{id:1,nombre:'Cancha E2E',duracionMinutos:90},disponibleEseDia:true,horarios:[]}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await expect(page.locator('#w2bAvailabilitySummary')).toContainText('No encontramos alternativas');await expect(page.locator('.w2b-availability-card')).toContainText('Completa');await expect(page.locator('#listaHorarios')).toContainText('Las canchas están completas');await expect(page.locator('[data-w2b-other-date]')).toBeVisible()});

test('W2.5A1A diferencia cierre y elimina seleccion invalida',async({page})=>{await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-18',cancha:{id:1,nombre:'Cancha E2E',duracionMinutos:90},disponibleEseDia:false,horarios:[]}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await expect(page.locator('body')).toHaveAttribute('data-booking-step','2');await expect(page.locator('.w2b-hero')).toBeHidden();await expect(page.locator('.w2b-availability-card')).not.toHaveClass(/selected/);await expect(page.locator('.w2b-availability-card')).toHaveClass(/consulted/);await expect(page.locator('.w2b-empty-smart')).toContainText('El complejo está cerrado este día');await expect(page.locator('[data-w2b-other-date]')).toBeVisible()});
test('W2.5A1A diferencia agenda completa de dia cerrado',async({page})=>{await page.route('**/api/publica/disponibilidad**',r=>r.fulfill({json:{fecha:'2026-10-18',cancha:{id:1,nombre:'Cancha E2E',duracionMinutos:90},disponibleEseDia:true,horarios:[]}}));await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();await expect(page.locator('.w2b-empty-smart')).toContainText('Las canchas están completas');await page.locator('[data-w2b-other-date]').click();await expect(page.locator('[data-panel="1"]')).toBeVisible();await expect(page.locator('#w2calTrigger')).toBeFocused()});

test('W2.5A1B horarios exponen interaccion premium accesible',async({page})=>{await page.goto('/w2/reservar');await page.locator('.reserve-court').first().click();await page.locator('#buscarHorarios').click();const row=page.locator('.reserve-time').first(),choice=row.locator('.reserve-time-choice');await expect(row).toBeVisible();await row.hover();const hovered=await row.evaluate(e=>({border:getComputedStyle(e).borderColor,transform:getComputedStyle(e).transform}));expect(hovered.border).not.toBe('rgb(45, 58, 64)');await expect(choice).toHaveCSS('color','rgb(255, 255, 255)');await row.focus();await expect(row).toBeFocused();await page.keyboard.press('Enter');await expect(page.locator('[data-panel="3"]')).toBeVisible()});
